def clean(s: any) -> str {
    if not s {
        return "";
    }
    t = html.unescape(str(s));
    t = re.sub("<[^>]+>", " ", t);
    t = re.sub("[ \\t]+", " ", t);
    t = re.sub("\\n\\s*\\n+", "\n\n", t);
    return t.strip();
}

