"""SettingsModal -- edit the idle-text preference."""

import from endpoints { Settings, set_idle_text }
import from .ui.dialog { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter }
import from .ui.button { Button }
import from .ui.input { Input }
import from .ui.label { Label }


def:pub SettingsModal(
    settings: Settings | None,
    onClose: Callable[[], None],
    onSaved: Callable[[Settings], None]
) -> JsxElement {
    # TODO: implement
}

def:pub set_idle_text(text: str) -> Settings {
    for st in [root-->][?:Settings] {
        st.idle_text = text;
        return st;
    }
    st = Settings(idle_text=text);
    root ++> st;
    return st;
}

