{"path": "components/SettingsModal.jac", "edits": [{"oldText": "def:pub SettingsModal(
    settings: Settings | None,
    onClose: Callable[[], None],
    onSaved: Callable[[Settings], None]
) -> JsxElement {
    # TODO: implement
}", "newText": "def:pub SettingsModal(
    settings: Settings | None,
    onClose: Callable[[], None],
    onSaved: Callable[[Settings], None]
) -> JsxElement {
    has idle_text: str = settings.idle_text if settings is not None else "( :3 )=3";
    has saving: bool = False;

    def set_idle(e: ChangeEvent) -> None { idle_text = e.target.value; }

    async def save -> None {
        saving = True;
        s = await set_idle_text(idle_text);
        onSaved(s);
        saving = False;
    }

    def handle_open_change(open: bool) -> None {
        if not open { onClose(); }
    }

    <Dialog open={True} onOpenChange={handle_open_change}>
        <DialogContent className="max-w-md">
            <DialogHeader>
                <DialogTitle>Settings</DialogTitle>
            </DialogHeader>

            <div className="flex flex-col gap-2">
                <Label htmlFor="idle-text">Idle text</Label>
                <Input
                    id="idle-text"
                    value={idle_text}
                    onChange={set_idle}
                    placeholder="( :3 )=3"
                />
                <p className="text-xs text-muted-foreground">
                    Shown on the floating widget when no pomodoro is running.
                </p>
            </div>

            <DialogFooter className="flex gap-2 justify-end">
                <Button variant="ghost" onClick={onClose}>Cancel</Button>
                <Button onClick={save} disabled={saving or not idle_text}>Save</Button>
            </DialogFooter>
        </DialogContent>
    </Dialog>
}"}]}

